import ast
from pathlib import Path
old='flash_attn==2.7.4.post1'; new='flash_attn>=2.7.4.post1'
def setup_deps(s):
    return ast.literal_eval(next(k.value for n in ast.walk(ast.parse(s)) if isinstance(n,ast.Call) and isinstance(n.func,ast.Name) and n.func.id=='setup' for k in n.keywords if k.arg=='install_requires'))
for path,read in [('requirements.txt',str.splitlines),('setup.py',setup_deps)]:
    s=Path(path).read_text(); assert s.count(old)==1
    a=read(s); b=read(s.replace(old,new,1)); assert len(a)==len(b)
    d=[(x,y) for x,y in zip(a,b) if x!=y]; assert d==[(old,new)]
    print(path, d, 'unchanged entries:',len(a)-1)

